def score_of_parentheses(s):
    def score(sub):                                                        # recursively score one balanced string, splitting at top-level pairs
        if sub == '()':
            return 1
        if sub[0] == '(' and sub[-1] == ')' and is_one_group(sub):
            return 2 * score(sub[1:-1])
        parts = split_top_level(sub)                                       # split into top-level balanced pieces, sum their scores
        return sum(score(p) for p in parts)

    def is_one_group(sub):
        depth = 0
        for i, c in enumerate(sub):
            depth += 1 if c == '(' else -1
            if depth == 0 and i != len(sub) - 1:
                return False                                               # depth returned to 0 before the very end: NOT a single group
        return True

    def split_top_level(sub):
        parts, depth, start = [], 0, 0
        for i, c in enumerate(sub):
            depth += 1 if c == '(' else -1
            if depth == 0:
                parts.append(sub[start:i + 1])
                start = i + 1
        return parts

    return score(s)


if __name__ == "__main__":
    print(score_of_parentheses("(()(()))"))

