using namespace std;

bool isOneGroup(const string& sub) {
    int depth = 0;
    for (int i = 0; i < (int)sub.size(); i++) {
        depth += (sub[i] == '(') ? 1 : -1;
        if (depth == 0 && i != (int)sub.size() - 1) return false;                     // depth returned to 0 before the very end: NOT a single group
    }
    return true;
}

vector<string> splitTopLevel(const string& sub) {
    vector<string> parts;
    int depth = 0, start = 0;
    for (int i = 0; i < (int)sub.size(); i++) {
        depth += (sub[i] == '(') ? 1 : -1;
        if (depth == 0) {
            parts.push_back(sub.substr(start, i - start + 1));
            start = i + 1;
        }
    }
    return parts;
}

int score(const string& sub) {                                                           // recursively score one balanced string, splitting at top-level pairs
    if (sub == "()") return 1;
    if (sub.front() == '(' && sub.back() == ')' && isOneGroup(sub)) {
        return 2 * score(sub.substr(1, sub.size() - 2));
    }
    int total = 0;
    for (auto& part : splitTopLevel(sub)) total += score(part);                             // split into top-level balanced pieces, sum their scores
    return total;
}

int scoreOfParentheses(string s) {
    return score(s);
}

