    stack = [0]                                                            # stack[-1] accumulates the score of the CURRENT nesting level
    for c in s:
        if c == '(':
            stack.append(0)                                                # a fresh, empty nesting level begins
        else:
            v = stack.pop()                                                # the just-completed level's total score
            add = 1 if v == 0 else 2 * v                                  # "()" scores exactly 1; anything nested doubles
            stack[-1] += add                                               # fold the completed level's score into its PARENT level
    return stack[0]


