public class Main {
    int scoreOfParentheses(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);                                                                  // stack top accumulates the score of the CURRENT nesting level
        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(0);                                                             // a fresh, empty nesting level begins
            } else {
                int v = stack.pop();                                                        // the just-completed level's total score
                int add = (v == 0) ? 1 : 2 * v;                                              // "()" scores exactly 1; anything nested doubles
                stack.push(stack.pop() + add);                                               // fold the completed level's score into its PARENT level
            }
        }
        return stack.pop();
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.scoreOfParentheses("()(())"));
    }
}

